pages.components/Footer.tsx:
export default function Footer({ data }: any) {
  const footerLinks = {
    Product: ["AI Builder", "Templates", "Live Preview", "Deploy"],
    Company: ["About", "Features", "Pricing", "Contact"],
    Legal: ["Privacy Policy", "Terms of Service", "Cookies"]};

  return (
    <footer className="bg-black text-white">
      <div className="max-w-7xl mx-auto px-6 lg:px-10 py-20">
        <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-12">
          {/* Brand */}
          <div>
            <h2 className="text-2xl font-bold">
              {data?.siteName || "ClyraUI"}
            </h2>

            <p className="mt-4 text-gray-400 leading-7">
              {data?.footerText ||
                "Build stunning AI-powered websites with smart templates, live editing, and seamless deployment."}
            </p>

            <div className="mt-6 flex gap-4 text-sm text-gray-400">
              <a href="#">LinkedIn</a>
              <a href="#">Twitter</a>
              <a href="#">GitHub</a>
            </div>
          </div>

          {/* Dynamic Columns */}
          {Object.entries(footerLinks).map(([title, links]) => (
            <div key={title}>
              <h3 className="text-lg font-semibold">{title}</h3>

              <div className="mt-4 flex flex-col gap-3 text-gray-400">
                {(links).map((link, index) => (
                  <a
                    key={index}
                    href="#"
                    className="hover:text-white transition"
                  >
                    {link}
                  </a>
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* Bottom */}
        <div className="mt-16 pt-8 border-t border-white/10 flex flex-col md:flex-row justify-between gap-4 text-sm text-gray-400">
          <p>
            © {new Date().getFullYear()}{" "}
            {data?.siteName || "ClyraUI"}. All rights reserved.
          </p>

          <p>Made with ❤️ by ClyraUI AI Builder</p>
        </div>
      </div>
    </footer>
  );
}

