export default function ServicesSection({ data }: any) {
  const services = [
    {
      icon: "⚡",
      title: "AI Page Generation",
      description:
        "Generate complete landing pages, business websites, and SaaS layouts instantly with smart AI prompts."},
    {
      icon: "🎨",
      title: "Drag & Drop Builder",
      description:
        "Customize every section visually with real-time editing, smooth drag-drop blocks, and instant layout updates."},
    {
      icon: "📱",
      title: "Responsive Design",
      description:
        "Every generated website is mobile-first, tablet-ready, and perfectly optimized for all screen sizes."},
    {
      icon: "🚀",
      title: "One Click Deployment",
      description:
        "Publish websites instantly with production-ready deployment pipelines and seamless hosting integrations."},
    {
      icon: "🔒",
      title: "Authentication Ready",
      description:
        "Built-in support for login, signup, Google auth, and secure protected dashboard experiences."},
    {
      icon: "💻",
      title: "Code Export",
      description:
        "Export clean React, Next.js, and Tailwind production code instantly for full developer flexibility."},
  ];

  return (
    <section id="services" className="py-24 bg-gray-50">
      <div className="max-w-7xl mx-auto px-6 lg:px-10">
        {/* Heading */}
        <div className="max-w-3xl">
          <p className="text-sm font-semibold uppercase tracking-widest text-gray-500 mb-4">
            Powerful Features
          </p>

          <h2 className="text-4xl lg:text-5xl font-bold tracking-tight text-gray-900">
            {data?.servicesTitle ||
              "Everything you need to build faster with AI"}
          </h2>

          <p className="mt-6 text-lg text-gray-600 leading-8">
            {data?.servicesText ||
              "ClyraUI combines smart AI generation, visual editing, deployment, and export tools to help teams ship beautiful websites in minutes."}
          </p>
        </div>

        {/* Cards */}
        <div className="mt-16 grid sm:grid-cols-2 lg:grid-cols-3 gap-8">
          {services.map((service, index) => (
            <div
              key={index}
              className="group bg-white rounded-3xl border border-gray-200 p-8 hover:shadow-2xl hover:-translate-y-1 transition-all duration-300"
            >
              <div className="text-4xl">{service.icon}</div>

              <h3 className="mt-6 text-xl font-semibold text-gray-900">
                {service.title}
              </h3>

              <p className="mt-4 text-gray-600 leading-7">
                {service.description}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
